#!/usr/bin/env bash
# Licence gate and attribution file for the npm dependencies we ship (#2754).
#
#   scripts/ci/npm-licenses.sh check      fail on a disallowed licence, or when
#                                         the web UI's attribution file is stale
#   scripts/ci/npm-licenses.sh generate   write web-ui/THIRD-PARTY-LICENSES.txt
#
# Covers production dependencies only, for the two npm projects:
#   web-ui         built to a static site and embedded in the daemon. Its bundle
#                  carries none of its packages' copyright notices, so the
#                  generated file supplies them (MIT and BSD ask for the notice
#                  to travel with copies).
#   agent-runtime  its release tarball holds our compiled code plus package.json
#                  and the lockfile; the packages themselves are installed from
#                  npm inside the customer's box. Gated, not redistributed.
#
# Same allow-list as the Go check (scripts/ci/check-licenses.sh), plus 0BSD,
# which is as permissive as ISC. Needs node 20+, npm and python3.
set -euo pipefail
cd "$(dirname "$0")/../.."

mode="${1:?usage: npm-licenses.sh check|generate}"
CHECKER="license-checker-rseidelsohn@5.0.1"
OUT="web-ui/THIRD-PARTY-LICENSES.txt"
ALLOWED="Apache-2.0 MIT BSD-2-Clause BSD-3-Clause ISC Unlicense MPL-2.0 0BSD"

# Packages that are in the installed production tree but not allowed by the
# list, each with why that is acceptable. Matched by name prefix.
#   web-ui:        @img/sharp-libvips-*  LGPL-3.0. Optional native binaries of
#                  Next's image optimiser. The site is a static export with
#                  unoptimised images (checked below), so none reach the files
#                  we embed and serve.
#                  caniuse-lite  CC-BY-4.0 browser-support data read by the
#                  build tools; not part of the output.
#   agent-runtime: @anthropic-ai/claude-agent-sdk*  Anthropic's own SDK under
#                  its commercial terms (not an open-source licence). We do not
#                  redistribute it: it is installed from npm in the customer's
#                  box, where its terms apply to them.
WEB_EXCEPT="@img/sharp-libvips-,caniuse-lite"
RT_EXCEPT="@anthropic-ai/claude-agent-sdk"

work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

# scan <project dir> <label>: install production deps in a scratch copy (never
# the working tree) and write $work/<label>.json.
scan() {
  local dir="$1" label="$2"
  mkdir -p "$work/$label"
  cp "$dir/package.json" "$dir/package-lock.json" "$work/$label/"
  (cd "$work/$label" && npm ci --omit=dev --ignore-scripts --no-audit --no-fund >/dev/null 2>&1) \
    || { echo "::error::npm ci failed for $dir" >&2; exit 1; }
  (cd "$work/$label" && npx --yes "$CHECKER" --production --excludePrivatePackages --json) \
    > "$work/$label.json"
}

# analyse <label> <exceptions> <mode>  (python: one place for the expression logic)
analyse() {
  python3 - "$work/$1.json" "$2" "$ALLOWED" "$3" "${4:-}" <<'PY'
import json, re, sys, os
path, excepts, allowed, mode, out = sys.argv[1:6]
allowed = set(allowed.split()); excepts = [e for e in excepts.split(",") if e]
data = json.load(open(path))

def ok(expr):
    expr = expr.strip()
    # SPDX: AND needs every side allowed, OR needs one. Parentheses dropped;
    # the packages in practice use flat expressions.
    expr = expr.replace("(", " ").replace(")", " ")
    for alt in re.split(r"\s+OR\s+", expr):
        if all(t.strip().rstrip("*") in allowed for t in re.split(r"\s+AND\s+", alt.strip())):
            return True
    return False

bad, kept = [], {}
for key, v in data.items():
    name = key.rsplit("@", 1)[0]
    lic = v.get("licenses")
    lic = " OR ".join(lic) if isinstance(lic, list) else str(lic)
    if any(name.startswith(e) for e in excepts):
        continue
    kept[key] = (lic, v)
    if not ok(lic):
        bad.append(f"{key}: {lic}")
if bad:
    print("::error::npm licence not on the allow-list:", file=sys.stderr)
    for b in sorted(bad): print("  " + b, file=sys.stderr)
    sys.exit(1)
print(f"npm licences ok: {len(kept)} packages ({len(data) - len(kept)} excepted)")

if mode == "generate":
    lines = ["Third-party software in the Containarium web UI", "=" * 47, "",
             "The web UI served by the daemon is built from the packages below.",
             "Each is distributed under the licence named; its notice follows.",
             "Generated by scripts/ci/npm-licenses.sh; do not edit.", ""]
    for key in sorted(kept):
        lic, v = kept[key]
        lines += ["-" * 80, f"{key}", f"License: {lic}"]
        if v.get("repository"): lines.append(f"Source: {v['repository']}")
        lines.append("")
        lf = v.get("licenseFile")
        text = ""
        if lf and re.match(r"(?i)(licen[cs]e|copying)", os.path.basename(lf)) and os.path.isfile(lf):
            text = open(lf, errors="replace").read().strip()
        elif v.get("copyright"):
            text = v["copyright"].strip()
        lines += [text or "(No licence text ships with this package; see its source repository.)", ""]
        # Apache-2.0 section 4(d): carry the package's NOTICE text too.
        pkgdir = os.path.dirname(lf) if lf else ""
        for nf in ("NOTICE", "NOTICE.txt", "NOTICE.md"):
            np_ = os.path.join(pkgdir, nf)
            if pkgdir and os.path.isfile(np_):
                lines += [f"NOTICE for {key}:", "", open(np_, errors="replace").read().strip(), ""]
                break
    open(out, "w").write("\n".join(lines))
elif mode == "check-file":
    text = open(out).read()
    miss = [k for k in kept if f"\n{k}\n" not in text]
    if miss:
        print("::error::web-ui/THIRD-PARTY-LICENSES.txt is missing or stale for:", file=sys.stderr)
        for m in sorted(miss): print("  " + m, file=sys.stderr)
        print("regenerate: scripts/ci/npm-licenses.sh generate", file=sys.stderr)
        sys.exit(1)
PY
}

# The exception for the LGPL image binaries holds only while the site is a
# static export with unoptimised images.
grep -q "output: 'export'" web-ui/next.config.ts && grep -q "unoptimized: true" web-ui/next.config.ts \
  || { echo "::error::web-ui/next.config.ts no longer sets output: 'export' and images.unoptimized; the sharp-libvips (LGPL) exception in scripts/ci/npm-licenses.sh no longer holds" >&2; exit 1; }

scan web-ui web
case "$mode" in
generate)
  # The scratch copy has the real files, so licence paths resolve there.
  analyse web "$WEB_EXCEPT" generate "$OUT"
  echo "wrote $OUT"
  ;;
check)
  analyse web "$WEB_EXCEPT" check-file "$OUT"
  scan agent-runtime rt
  analyse rt "$RT_EXCEPT" check
  ;;
*) echo "usage: npm-licenses.sh check|generate" >&2; exit 2 ;;
esac
